//! The proof that a C caller can fill a struct and pass it, and pass an array of them.
//!
//! The probes are compiled here, through the real attribute, and the header they would
//! produce is generated by `rorolala-dev-bindgen` and handed to a C11 compiler. The
//! probes stay in this test because they are a proof of the framework rather than a part
//! of the surface: the real request types arrive with the exports that use them.

use std::ffi::{CStr, c_char};
use std::fs;
use std::mem::size_of;
use std::process::Command;

use rorolala_utils_lazyffi::{
    InputRef, InputType, RolaStrSpan, RorolalaResult, RorolalaResultTag, StrSpan, free_string,
};

include!("support/probes.rs");

/// The request the probes read, in the repr C would fill.
fn request_repr() -> RolaProbeRequest {
    // The span points at an array of pointers, so the array has to outlive every call
    // this repr is passed to. Leaking it for the test binary is enough, and keeps the
    // repr buildable by an ordinary function.
    let items: &'static [*const c_char] = Box::leak(Box::new([
        c"art/hero.psd".as_ptr(),
        c"art/hero.png".as_ptr(),
    ]));

    RolaProbeRequest {
        workspace: c"studio".as_ptr().cast_mut(),
        account: c"alice".as_ptr().cast_mut(),
        files: RolaStrSpan {
            items: items.as_ptr(),
            count: items.len(),
        },
        offline: true,
        force: false,
    }
}

/// Reads a successful result's string payload, releasing it.
fn payload_string(result: RorolalaResult) -> String {
    assert_eq!(result.tag, RorolalaResultTag::Ok, "the probe succeeds");

    let pointer = result.payload.cast::<c_char>();
    assert!(!pointer.is_null(), "a string payload is not null");

    // SAFETY: the payload of a successful probe is the `char *` the export allocated, so
    // it is a live NUL-terminated C string.
    let text = unsafe { CStr::from_ptr(pointer) }
        .to_string_lossy()
        .into_owned();

    // SAFETY: the pointer came from this result and has not been released.
    unsafe { free_string(pointer) };

    text
}

#[test]
fn a_str_span_copies_every_string() {
    let items: [*const c_char; 2] = [c"one".as_ptr(), c"two".as_ptr()];
    let repr = RolaStrSpan {
        items: items.as_ptr(),
        count: items.len(),
    };

    // SAFETY: the repr points at two live C strings and says so.
    let span = unsafe { <StrSpan as InputType>::input_type(repr) };

    assert_eq!(span.into_vec(), ["one".to_owned(), "two".to_owned()]);

    // A zeroed span is a list with nothing in it, not a read of a null pointer.
    // SAFETY: a null pointer with a count of zero is what the conversion answers first.
    let empty = unsafe {
        <StrSpan as InputType>::input_type(RolaStrSpan {
            items: std::ptr::null(),
            count: 0,
        })
    };
    assert!(empty.as_slice().is_empty());
}

#[test]
fn an_input_struct_converts_each_field() {
    // SAFETY: every pointer in the repr is a live C string, and the span points at two.
    let request = unsafe { <ProbeRequest as InputType>::input_type(request_repr()) };

    assert_eq!(request.workspace, "studio");
    assert_eq!(request.account, "alice");
    assert_eq!(
        request.files.as_slice(),
        ["art/hero.psd".to_owned(), "art/hero.png".to_owned()]
    );
    assert!(request.offline);
    assert!(!request.force);
}

#[test]
fn a_borrowed_input_struct_is_built_and_held_for_the_call() {
    let repr = request_repr();

    // SAFETY: the pointer is to a live repr that outlives the borrow made here.
    let held = unsafe { <ProbeRequest as InputRef>::input_ref(core::ptr::from_ref(&repr)) };
    assert_eq!(held.workspace, "studio");
    assert_eq!(held.files.as_slice().len(), 2);

    // The same shape the generated wrapper takes: a const pointer to the repr, read for
    // the call and handed to the function as a borrow.
    // SAFETY: the pointer is the one above, once more, and the repr is still readable.
    let result = unsafe { rola_probe_request(core::ptr::from_ref(&repr)) };
    assert_eq!(
        payload_string(result),
        "studio|alice|art/hero.psd,art/hero.png|true|false"
    );
}

#[test]
fn a_slice_of_tagged_unions_converts_every_element() {
    let ops = [
        RolaProbeOp {
            tag: RolaProbeOpTag::CreateEntry,
            payload: RolaProbeOpPayload {
                CreateEntry: RolaProbeOpCreateEntry {
                    path: c"art/hero.psd".as_ptr().cast_mut(),
                },
            },
        },
        RolaProbeOp {
            tag: RolaProbeOpTag::RemoveEntry,
            payload: RolaProbeOpPayload {
                RemoveEntry: RolaProbeOpRemoveEntry {
                    uuid: c"0000".as_ptr().cast_mut(),
                },
            },
        },
    ];

    // SAFETY: the pointer and the count name the two live elements built above.
    let result = unsafe { rola_probe_ops(ops.as_ptr(), ops.len()) };

    assert_eq!(payload_string(result), "create:art/hero.psd;remove:0000");

    // An empty array is a valid call too, and the wrapper must not read a null pointer.
    // SAFETY: a count of zero means the pointer is never read.
    let empty = unsafe { rola_probe_ops(std::ptr::null(), 0) };
    assert_eq!(payload_string(empty), "");
}

/// The sized layout every pointer in this proof is written for.
const POINTER: usize = size_of::<*const c_char>();

#[test]
fn the_reprs_are_laid_out_the_way_the_header_states() {
    // The header's assertions are what a C compiler checks; these are the same numbers
    // stated on the Rust side, so a repr that drifts is caught before a caller meets it.
    assert_eq!(size_of::<RolaStrSpan>(), 2 * POINTER);
    // Five pointers' worth, because the two booleans share the last one's tail.
    assert_eq!(size_of::<RolaProbeRequest>(), 5 * POINTER);
    assert_eq!(size_of::<RolaProbeOp>(), 2 * POINTER);
}

#[test]
fn the_header_generator_renders_the_input_shapes_and_the_c_compiler_accepts_them() {
    let root = std::env::temp_dir().join(format!("rola-lazyffi-input-{}", std::process::id()));
    let _ = fs::remove_dir_all(&root);
    fs::create_dir_all(root.join("src")).expect("a source tree");
    fs::write(root.join("src/lib.rs"), include_str!("support/probes.rs")).expect("the probes");

    let output = root.join("out");
    let config = rorolala_dev_bindgen::Config {
        source_roots: std::slice::from_ref(&root),
        output_dir: &output,
        enforce_naming: true,
    };
    let header_path = rorolala_dev_bindgen::generate(&config).expect("the header generates");
    let header = fs::read_to_string(&header_path).expect("the header is written");

    // The span is a built-in, declared beside the result type.
    assert!(
        header.contains("typedef struct RolaStrSpan {\n  const char *const * items;\n  size_t count;\n} RolaStrSpan;"),
        "{header}"
    );

    // A transparent input struct writes every field C can fill, with a string as
    // read-only and a span by value.
    assert!(
        header.contains(
            "typedef struct RolaProbeRequest {\n\
             \x20 /** The workspace to look in. */\n\
             \x20 const char * workspace;\n\
             \x20 /** The account asking. */\n\
             \x20 const char * account;\n\
             \x20 /** The files to ask about. */\n\
             \x20 RolaStrSpan files;\n\
             \x20 /** Whether to stay off the network. */\n\
             \x20 bool offline;\n\
             \x20 /** Whether to redo work already done. */\n\
             \x20 bool force;\n\
             } RolaProbeRequest;"
        ),
        "{header}"
    );

    // A tagged union keeps the shape the enum exports already have.
    assert!(header.contains("RolaProbeOp_CreateEntry = 0,"), "{header}");
    assert!(header.contains("RolaProbeOp_RemoveEntry = 1,"), "{header}");
    assert!(
        header.contains("typedef struct RolaProbeOpCreateEntry {"),
        "{header}"
    );
    assert!(header.contains("char * path;"), "{header}");
    assert!(
        header.contains("  RolaProbeOpTag tag;\n  RolaProbeOpPayload payload;"),
        "{header}"
    );

    // A slice is a pointer and a count named the way the macro names them.
    assert!(
        header.contains("RorolalaResult rola_probe_request(const RolaProbeRequest * request);"),
        "{header}"
    );
    assert!(
        header.contains("RorolalaResult rola_probe_ops(const RolaProbeOp * ops, size_t ops_len);"),
        "{header}"
    );

    // Every transparent type states its size and each field's offset, the span included.
    assert!(
        header.contains("#define ROROLALA_ABI_SIZE_ROLASTRSPAN 16"),
        "{header}"
    );
    assert!(
        header.contains("#define ROROLALA_ABI_OFFSET_ROLASTRSPAN_ITEMS 0"),
        "{header}"
    );
    assert!(
        header.contains("#define ROROLALA_ABI_OFFSET_ROLASTRSPAN_COUNT 8"),
        "{header}"
    );
    assert!(
        header.contains("#define ROROLALA_ABI_SIZE_ROLAPROBEREQUEST 40"),
        "{header}"
    );
    assert!(
        header.contains("#define ROROLALA_ABI_OFFSET_ROLAPROBEREQUEST_FILES 16"),
        "{header}"
    );
    assert!(
        header.contains("#define ROROLALA_ABI_OFFSET_ROLAPROBEREQUEST_OFFLINE 32"),
        "{header}"
    );
    assert!(
        header.contains("#define ROROLALA_ABI_OFFSET_ROLAPROBEREQUEST_FORCE 33"),
        "{header}"
    );
    assert!(
        header.contains("#define ROROLALA_ABI_SIZE_ROLAPROBEOP 16"),
        "{header}"
    );
    assert!(
        header.contains("#define ROROLALA_ABI_OFFSET_ROLAPROBEOP_PAYLOAD 8"),
        "{header}"
    );

    // And what a caller writes against it, as C11 with every warning an error.
    let c_path = root.join("probe.c");
    fs::write(
        &c_path,
        r#"
#include <stddef.h>

#include "rorolala_ffi.h"

static const char *files[] = { "art/hero.psd", "art/hero.png" };

int main(void) {
    RolaProbeRequest request = {0};
    request.workspace = "studio";
    request.account = "alice";
    request.files.items = files;
    request.files.count = sizeof files / sizeof files[0];
    request.offline = true;

    RolaProbeOp ops[2];
    ops[0].tag = RolaProbeOp_CreateEntry;
    ops[0].payload.CreateEntry.path = "art/hero.psd";
    ops[1].tag = RolaProbeOp_RemoveEntry;
    ops[1].payload.RemoveEntry.uuid = "0000";

    RorolalaResult answered = rola_probe_request(&request);
    RorolalaResult applied = rola_probe_ops(ops, sizeof ops / sizeof ops[0]);

    return answered.tag != RorolalaResult_Ok || applied.tag != RorolalaResult_Ok;
}
"#,
    )
    .expect("the C proof is written");

    let compiler = std::env::var("CC").unwrap_or_else(|_| "cc".to_owned());
    let compiled = Command::new(&compiler)
        .arg("-std=c11")
        .arg("-Wall")
        .arg("-Wextra")
        .arg("-Werror")
        .arg("-fsyntax-only")
        .arg(format!("-I{}", output.display()))
        .arg(&c_path)
        .output();

    let Ok(output) = compiled else {
        eprintln!("note: no `{compiler}` to compile the C proof with, skipping that check");
        return;
    };

    assert!(
        output.status.success(),
        "the C proof did not compile:\n{}",
        String::from_utf8_lossy(&output.stderr)
    );
}
